class TokenBucket:
    def __init__(self, capacity: int, fill_rate: float):
        self.capacity = capacity
        self.fill_rate = fill_rate
        self.tokens = capacity
        self.last_time = 0.0

    def consume(self, tokens: int, now: float) -> bool:
        if self.tokens >= tokens:
            self.tokens -= tokens
            return True
        return False
